#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<int> to;
    vector<long long> cap;
    vector<vector<int>> graph(n + 1);
    for (const vector<long long>& ed : edges) {
        graph[ed[0]].push_back((int)to.size());
        to.push_back((int)ed[1]);
        cap.push_back(ed[2]);
        graph[ed[1]].push_back((int)to.size());
        to.push_back((int)ed[0]);
        cap.push_back(0);
    }
    long long flow = 0;
    for (;;) {
        vector<int> level(n + 1, -1);
        level[1] = 0;
        vector<int> queue = {1};
        for (size_t i = 0; i < queue.size(); i++) {
            int v = queue[i];
            for (int e : graph[v]) {
                if (cap[e] > 0 && level[to[e]] < 0) {
                    level[to[e]] = level[v] + 1;
                    queue.push_back(to[e]);
                }
            }
        }
        if (level[n] < 0) break;
        vector<int> pos(n + 1, 0);
        for (;;) {
            vector<int> path;
            int v = 1;
            while (v != n) {
                bool moved = false;
                while (pos[v] < (int)graph[v].size()) {
                    int e = graph[v][pos[v]];
                    if (cap[e] > 0 && level[to[e]] == level[v] + 1) {
                        path.push_back(e);
                        v = to[e];
                        moved = true;
                        break;
                    }
                    pos[v]++;
                }
                if (!moved) {
                    if (path.empty()) break;
                    int e = path.back();
                    path.pop_back();
                    v = to[e ^ 1];
                    pos[v]++;
                }
            }
            if (v != n) break;
            long long push = cap[path[0]];
            for (int e : path) push = min(push, cap[e]);
            for (int e : path) {
                cap[e] -= push;
                cap[e ^ 1] += push;
            }
            flow += push;
        }
    }
    cout << flow << "\n";

    return 0;
}

